using System;
using System.Collections.Generic;
using System.Text;

namespace PAWS.domain.Entities;

/// <summary>
/// The adoption form submitted by an adopter for one pet.
/// It moves through a status workflow that Staff and Admin manage.
/// </summary>
public class AdoptionApplication
{
    public int AdoptionApplicationId { get; set; }

    // A readable reference such as "APP-2026-00001".
    // It is generated by the API when the application is saved (Phase 17)
    // and will be made unique in Phase 5.
    public string ApplicationNumber { get; set; } = string.Empty;

    // Foreign keys.
    public int PetId { get; set; }           // the pet being applied for
    public int UserId { get; set; }          // the adopter who applied
    public int? ReviewedBy { get; set; }     // the Staff/Admin who reviewed it

    // Applicant details.
    public string? FullName { get; set; }
    public string? Email { get; set; }
    public string? Phone { get; set; }
    public string? Address { get; set; }
    public string? Occupation { get; set; }

    // Home and household details.
    public string? HousingType { get; set; }
    public string? HomeDescription { get; set; }
    public bool HasYard { get; set; }

    public bool HasOtherPets { get; set; }
    public string? OtherPetsDetails { get; set; }

    public bool HasChildren { get; set; }
    public string? ChildrenDetails { get; set; }

    public string? WorkingHours { get; set; }
    public string? ReasonForAdopting { get; set; }
    public string? PetExperience { get; set; }

    // Emergency contact.
    public string? EmergencyContactName { get; set; }
    public string? EmergencyContactPhone { get; set; }
    public string? EmergencyContactRelationship { get; set; }

    // Allowed values: "Submitted", "Under Review", "Approved",
    // "Rejected", "Completed", "Withdrawn".
    public string ApplicationStatus { get; set; } = "Submitted";

    public string? Remarks { get; set; }
    public string? RejectionReason { get; set; }

    public DateTime AppliedAt { get; set; } = DateTime.UtcNow;
    public DateTime? ReviewedAt { get; set; }

    public DateTime? InterviewDate { get; set; }
    public string? InterviewNotes { get; set; }

    public DateTime? CompletedAt { get; set; }

    // Soft delete: when this has a value, the record is treated as deleted
    // but stays in the database for history.
    public DateTime? DeletedAt { get; set; }

    // Navigation properties.
    public Pet? Pet { get; set; }
    public User? User { get; set; }       // the adopter
    public User? Reviewer { get; set; }   // the reviewing Staff/Admin
}
